package edu.synergy.algorithms.lists;
import java.util.*;
public final class StudentSorter { public static final class Student { private final int point; private final String fullName; public Student(int point,String fullName){this.point=point;this.fullName=fullName;} public int getPoint(){return point;} public String getFullName(){return fullName;} @Override public String toString(){return "Student{point="+point+", fullName='"+fullName+"'}";} } private StudentSorter(){} public static LinkedList<Student> selectionSortByAsc(Student[] students){Student[]a=students.clone();for(int i=0;i<a.length-1;i++){int min=i;for(int j=i+1;j<a.length;j++)if(a[j].getPoint()<a[min].getPoint())min=j;Student t=a[i];a[i]=a[min];a[min]=t;}return new LinkedList<>(Arrays.asList(a));} public static LinkedList<Student> selectionSort(List<Student> input){return selectionSortByAsc(input.toArray(Student[]::new));} }
